      })
      .from(member)
      .innerJoin(user, eq(member.userId, user.id))
      .leftJoin(userStats, eq(member.userId, userStats.userId))
      .where(and(eq(member.id, memberId), eq(member.organizationId, organizationId)))
      .limit(1)

